package com.hostelcheck.backend.controller;
import com.hostelcheck.backend.entity.*;import com.hostelcheck.backend.repository.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminController {private final PropertyListingRepository properties;private final UserAccountRepository users;private final InspectionRequestRepository inspections;private final FraudReportRepository reports;@Value("${app.admin-api-key:}")private String adminKey;public AdminController(PropertyListingRepository p,UserAccountRepository u,InspectionRequestRepository i,FraudReportRepository r){properties=p;users=u;inspections=i;reports=r;}
 private void check(String key){if(adminKey.isBlank()||key==null||!java.security.MessageDigest.isEqual(adminKey.getBytes(),key.getBytes()))throw new IllegalArgumentException("Admin access is not configured or the key is invalid.");}
 @GetMapping("/overview") public Map<String,Object>overview(@RequestHeader(value="X-Admin-Key",required=false)String key){check(key);return Map.of("users",users.count(),"agents",users.findAll().stream().filter(u->u.getRole().equals("House Agent")).count(),"pendingProperties",properties.findByStatusOrderByCreatedAtDesc("PENDING").size(),"inspectionRequests",inspections.count(),"fraudReports",reports.count());}
 @GetMapping("/properties/pending") public List<PropertyListing>pending(@RequestHeader(value="X-Admin-Key",required=false)String key){check(key);return properties.findByStatusOrderByCreatedAtDesc("PENDING");}
 @PatchMapping("/properties/{id}/decision") public Map<String,Object>decide(@RequestHeader(value="X-Admin-Key",required=false)String key,@PathVariable Long id,@RequestBody Map<String,Object>d){check(key);PropertyListing p=properties.findById(id).orElseThrow(()->new IllegalArgumentException("Property not found."));String decision=String.valueOf(d.getOrDefault("decision",""));if(!List.of("APPROVED","REJECTED").contains(decision))throw new IllegalArgumentException("Decision must be APPROVED or REJECTED.");p.setStatus(decision);p.setPropertyVerified(decision.equals("APPROVED"));properties.save(p);return Map.of("id",id,"status",decision,"propertyVerified",p.isPropertyVerified());}
 @GetMapping("/agents/pending") public List<Map<String,Object>>pendingAgents(@RequestHeader(value="X-Admin-Key",required=false)String key){check(key);return users.findAll().stream().filter(u->u.getRole().equals("House Agent")&&!u.isIdentityVerified()).map(u->Map.<String,Object>of("id",u.getId(),"name",u.getFullName(),"email",u.getEmail(),"phone",u.getPhone(),"businessName",u.getBusinessName(),"businessAddress",u.getBusinessAddress(),"operatingArea",u.getOperatingArea())).toList();}
 @PatchMapping("/agents/{id}/verification") public Map<String,Object>verifyAgent(@RequestHeader(value="X-Admin-Key",required=false)String key,@PathVariable Long id,@RequestBody Map<String,Object>d){check(key);UserAccount u=users.findById(id).orElseThrow(()->new IllegalArgumentException("Agent not found."));if(!u.getRole().equals("House Agent"))throw new IllegalArgumentException("The selected account is not a house agent.");boolean verified=Boolean.parseBoolean(String.valueOf(d.getOrDefault("verified","false")));u.setIdentityVerified(verified);users.save(u);return Map.of("id",id,"identityVerified",verified);}
 @GetMapping("/inspections") public List<InspectionRequest>allInspections(@RequestHeader(value="X-Admin-Key",required=false)String key){check(key);return inspections.findAll();}
 @PatchMapping("/inspections/{id}/status") public Map<String,Object>inspectionStatus(@RequestHeader(value="X-Admin-Key",required=false)String key,@PathVariable Long id,@RequestBody Map<String,Object>d){check(key);InspectionRequest r=inspections.findById(id).orElseThrow(()->new IllegalArgumentException("Inspection request not found."));String status=String.valueOf(d.getOrDefault("status",""));if(!List.of("PENDING","ACCEPTED","DECLINED","COMPLETED").contains(status))throw new IllegalArgumentException("Invalid inspection status.");r.setStatus(status);inspections.save(r);return Map.of("id",id,"status",status);}
 @PatchMapping("/fraud-reports/{id}/status") public Map<String,Object>fraudStatus(@RequestHeader(value="X-Admin-Key",required=false)String key,@PathVariable Long id,@RequestBody Map<String,Object>d){check(key);FraudReport r=reports.findById(id).orElseThrow(()->new IllegalArgumentException("Fraud report not found."));String status=String.valueOf(d.getOrDefault("status",""));if(!List.of("OPEN","INVESTIGATING","RESOLVED").contains(status))throw new IllegalArgumentException("Invalid fraud report status.");r.setStatus(status);reports.save(r);return Map.of("id",id,"status",status);}
 @GetMapping("/fraud-reports") public List<FraudReport>frauds(@RequestHeader(value="X-Admin-Key",required=false)String key){check(key);return reports.findAllByOrderByCreatedAtDesc();}
}
